🐛 Describe the bug
#include <torch/torch.h>
#include <iostream>
#include <c10/cuda/CUDAStream.h>

int main()
{
    // creat two tensors, and take their slices
    at::Tensor tAiF = at::randn({ 200, 3, 1080, 1440 }).to(at::kCUDA);
    at::Tensor tGrad = at::randn({ 200, 3, 1080, 1440 }).to(at::kCUDA);
    at::Tensor tAiFTmp = at::slice(tAiF, 2, 0, 100);
    at::Tensor tGradTmp = at::slice(tGrad, 2, 0, 100);

    // multiplication
    tAiF = tAiF * tGrad;
    tAiFTmp = tAiFTmp * tGradTmp;

    // Compare the results of multiplication
    // The result of multiplication is exactly the same
    // sample output
    //     tAiFTmpSub max abs 0.00000000000000000000
    //     tAiFTmpSub mean abs 0.00000000000000000000
    at::Tensor tAiFTmp2 = at::slice(tAiF, 2, 0, 100);
    at::Tensor tAiFTmpSub = tAiFTmp2 - tAiFTmp;
    at::Tensor tAiFTmpSubAbs = at::abs(tAiFTmpSub);
    std::cout << std::fixed << std::setprecision(20) << "tAiFTmpSub max abs " << at::max(tAiFTmpSubAbs).item() << std::endl;
    std::cout << std::fixed << std::setprecision(20) << "tAiFTmpSub mean abs " << at::mean(tAiFTmpSubAbs).item() << std::endl;

    // Sum over dimension 0
    at:: Tensor tAiFSum = at::sum(tAiF, 0);
    at::Tensor tAiFTmpSum = at::sum(tAiFTmp, 0);

    // Print the result of the sum
    // The results of the sum will vary
    // sample output
    //     tAiFSum[0, 0, 0] 14.05858135223388671875
    //     tAiFTmpSum[0, 0, 0] 14.05858039855957031250
    std::cout << std::fixed << std::setprecision(20) << "tAiFSum[0, 0, 0] " << tAiFSum.index({ 0, 0, 0 }).item() << std::endl;
    std::cout << std::fixed << std::setprecision(20) << "tAiFTmpSum[0, 0, 0] " << tAiFTmpSum.index({ 0, 0, 0 }).item() << std::endl;

    return 0;
}

